[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Fresh Pantry — Discover Everyday Deliciousness</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Fredoka:wght@400;500;600;700&family=Nunito:wght@300;400;500;600;700&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }

    :root {
      --color-primary: #2D6A4F;
      --color-primary-dark: #1B4332;
      --color-accent: #F4A261;
      --color-accent-warm: #E76F51;
      --color-bg: #FEFAE0;
      --color-bg-alt: #F5F0E1;
      --color-surface: #FFFFFF;
      --color-text: #2B2B2B;
      --color-text-light: #5A5A5A;
      --color-border: #E8E2CC;
      --font-heading: 'Fredoka', sans-serif;
      --font-body: 'Nunito', sans-serif;
      --radius-sm: 8px;
      --radius-md: 12px;
      --radius-lg: 20px;
      --radius-xl: 28px;
      --shadow-sm: 0 2px 8px rgba(45, 106, 79, 0.08);
      --shadow-md: 0 4px 16px rgba(45, 106, 79, 0.12);
      --shadow-lg: 0 8px 32px rgba(45, 106, 79, 0.16);
      --transition-fast: 150ms ease-out;
      --transition-base: 250ms ease-out;
      --transition-slow: 350ms ease-out;
      --max-width: 1200px;
      --z-nav: 100;
    }

    html {
      scroll-behavior: smooth;
    }

    body {
      font-family: var(--font-body);
      background-color: var(--color-bg);
      color: var(--color-text);
      line-height: 1.6;
      font-size: 16px;
      -webkit-font-smoothing: antialiased;
    }

    /* Accessibility */
    .sr-only {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0, 0, 0, 0);
      white-space: nowrap;
      border: 0;
    }

    :focus-visible {
      outline: 3px solid var(--color-accent);
      outline-offset: 2px;
    }

    /* Skip link */
    .skip-link {
      position: absolute;
      top: -100%;
      left: 16px;
      padding: 12px 24px;
      background: var(--color-primary);
      color: white;
      font-weight: 600;
      border-radius: var(--radius-md);
      z-index: 1000;
      text-decoration: none;
    }
    .skip-link:focus {
      top: 16px;
    }

    /* ==================== HEADER ==================== */
    .header {
      position: sticky;
      top: 0;
      z-index: var(--z-nav);
      background: rgba(254, 250, 224, 0.95);
      backdrop-filter: blur(12px);
      -webkit-backdrop-filter: blur(12px);
      border-bottom: 1px solid var(--color-border);
      padding: 0 24px;
    }

    .header__inner {
      max-width: var(--max-width);
      margin: 0 auto;
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 72px;
    }

    .logo {
      display: flex;
      align-items: center;
      gap: 10px;
      text-decoration: none;
      color: var(--color-primary);
    }

    .logo__icon {
      width: 40px;
      height: 40px;
    }

    .logo__text {
      font-family: var(--font-heading);
      font-size: 1.5rem;
      font-weight: 700;
      letter-spacing: -0.02em;
    }

    .nav {
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .nav__link {
      font-family: var(--font-body);
      font-weight: 600;
      font-size: 0.95rem;
      color: var(--color-text);
      text-decoration: none;
      padding: 8px 16px;
      border-radius: var(--radius-md);
      transition: background var(--transition-fast), color var(--transition-fast);
    }

    .nav__link:hover {
      background: var(--color-primary);
      color: white;
    }

    .nav__link--cta {
      background: var(--color-primary);
      color: white;
    }

    .nav__link--cta:hover {
      background: var(--color-primary-dark);
    }

    .mobile-menu-btn {
      display: none;
      background: none;
      border: none;
      padding: 8px;
      cursor: pointer;
      border-radius: var(--radius-sm);
    }

    /* ==================== HERO ==================== */
    .hero {
      position: relative;
      overflow: hidden;
      padding: 80px 24px 100px;
      text-align: center;
    }

    .hero::before {
      content: '';
      position: absolute;
      top: -50%;
      right: -20%;
      width: 600px;
      height: 600px;
      background: radial-gradient(circle, rgba(244, 162, 97, 0.2) 0%, transparent 70%);
      pointer-events: none;
    }

    .hero::after {
      content: '';
      position: absolute;
      bottom: -30%;
      left: -10%;
      width: 400px;
      height: 400px;
      background: radial-gradient(circle, rgba(45, 106, 79, 0.12) 0%, transparent 70%);
      pointer-events: none;
    }

    .hero__inner {
      max-width: var(--max-width);
      margin: 0 auto;
      position: relative;
      z-index: 1;
    }

    .hero__badge {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: var(--color-surface);
      border: 2px solid var(--color-accent);
      color: var(--color-accent-warm);
      font-weight: 700;
      font-size: 0.85rem;
      padding: 8px 20px;
      border-radius: 50px;
      margin-bottom: 24px;
      animation: fadeInDown 0.6s ease-out;
    }

    .hero__title {
      font-family: var(--font-heading);
      font-size: clamp(2.5rem, 6vw, 4rem);
      font-weight: 700;
      line-height: 1.1;
      color: var(--color-primary);
      margin-bottom: 20px;
      animation: fadeInUp 0.6s ease-out 0.1s both;
    }

    .hero__subtitle {
      font-size: clamp(1.1rem, 2vw, 1.35rem);
      color: var(--color-text-light);
      max-width: 600px;
      margin: 0 auto 40px;
      animation: fadeInUp 0.6s ease-out 0.2s both;
    }

    .hero__actions {
      display: flex;
      gap: 16px;
      justify-content: center;
      flex-wrap: wrap;
      animation: fadeInUp 0.6s ease-out 0.3s both;
    }

    .btn {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      font-family: var(--font-body);
      font-weight: 700;
      font-size: 1rem;
      padding: 14px 28px;
      border-radius: var(--radius-lg);
      border: none;
      cursor: pointer;
      text-decoration: none;
      transition: transform var(--transition-fast), box-shadow var(--transition-fast), background var(--transition-fast);
    }

    .btn:active {
      transform: scale(0.97);
    }

    .btn--primary {
      background: var(--color-primary);
      color: white;
      box-shadow: 0 4px 14px rgba(45, 106, 79, 0.35);
    }

    .btn--primary:hover {
      background: var(--color-primary-dark);
      transform: translateY(-2px);
      box-shadow: 0 6px 20px rgba(45, 106, 79, 0.4);
    }

    .btn--secondary {
      background: var(--color-surface);
      color: var(--color-primary);
      border: 2px solid var(--color-primary);
    }

    .btn--secondary:hover {
      background: var(--color-primary);
      color: white;
      transform: translateY(-2px);
    }

    /* ==================== SECTIONS ==================== */
    .section {
      padding: 80px 24px;
    }

    .section--alt {
      background: var(--color-surface);
    }

    .section__inner {
      max-width: var(--max-width);
      margin: 0 auto;
    }

    .section__header {
      text-align: center;
      margin-bottom: 48px;
    }

    .section__title {
      font-family: var(--font-heading);
      font-size: clamp(1.8rem, 4vw, 2.5rem);
      font-weight: 700;
      color: var(--color-text);
      margin-bottom: 12px;
    }

    .section__subtitle {
      font-size: 1.1rem;
      color: var(--color-text-light);
      max-width: 560px;
      margin: 0 auto;
    }

    /* ==================== STATS BANNER ==================== */
    .stats {
      background: var(--color-primary);
      padding: 60px 24px;
      position: relative;
      overflow: hidden;
    }

    .stats::before {
      content: '';
      position: absolute;
      top: 0;
      left: 0;
      right: 0;
      bottom: 0;
      background: url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23ffffff' fill-opacity='0.05'%3E%3Ccircle cx='30' cy='30' r='4'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E");
      pointer-events: none;
    }

    .stats__inner {
      max-width: var(--max-width);
      margin: 0 auto;
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 32px;
      position: relative;
      z-index: 1;
    }

    .stat {
      text-align: center;
    }

    .stat__number {
      font-family: var(--font-heading);
      font-size: clamp(2.2rem, 5vw, 3.5rem);
      font-weight: 700;
      color: white;
      line-height: 1;
      margin-bottom: 8px;
    }

    .stat__label {
      font-size: 0.95rem;
      color: rgba(255, 255, 255, 0.85);
      font-weight: 500;
    }

    /* ==================== FEATURED PRODUCTS CAROUSEL ==================== */
    .carousel {
      position: relative;
    }

    .carousel__track-container {
      overflow: hidden;
      margin: 0 -24px;
      padding: 0 24px;
    }

    .carousel__track {
      display: flex;
      gap: 20px;
      overflow-x: auto;
      scroll-snap-type: x mandatory;
      scrollbar-width: none;
      -ms-overflow-style: none;
      padding: 8px 0;
    }

    .carousel__track::-webkit-scrollbar {
      display: none;
    }

    .carousel__btn {
      position: absolute;
      top: 50%;
      transform: translateY(-50%);
      width: 48px;
      height: 48px;
      border-radius: 50%;
      background: var(--color-surface);
      border: 2px solid var(--color-border);
      box-shadow: var(--shadow-md);
      cursor: pointer;
      display: flex;
      align-items: center;
      justify-content: center;
      transition: all var(--transition-fast);
      z-index: 10;
    }

    .carousel__btn:hover {
      background: var(--color-primary);
      border-color: var(--color-primary);
    }

    .carousel__btn:hover svg {
      stroke: white;
    }

    .carousel__btn svg {
      width: 24px;
      height: 24px;
      stroke: var(--color-text);
      stroke-width: 2.5;
      fill: none;
    }

    .carousel__btn--prev {
      left: 8px;
    }

    .carousel__btn--next {
      right: 8px;
    }

    .product-card {
      flex: 0 0 260px;
      scroll-snap-align: start;
      background: var(--color-surface);
      border-radius: var(--radius-xl);
      overflow: hidden;
      box-shadow: var(--shadow-sm);
      transition: transform var(--transition-base), box-shadow var(--transition-base);
      cursor: pointer;
    }

    .product-card:hover {
      transform: translateY(-6px);
      box-shadow: var(--shadow-lg);
    }

    .product-card__image {
      width: 100%;
      height: 200px;
      background: linear-gradient(135deg, #E8F5E9 0%, #C8E6C9 100%);
      display: flex;
      align-items: center;
      justify-content: center;
      position: relative;
      overflow: hidden;
    }

    .product-card__image svg {
      width: 80px;
      height: 80px;
      opacity: 0.5;
    }

    .product-card__content {
      padding: 20px;
    }

    .product-card__name {
      font-family: var(--font-heading);
      font-size: 1.15rem;
      font-weight: 600;
      color: var(--color-text);
      margin-bottom: 6px;
      line-height: 1.3;
    }

    .product-card__desc {
      font-size: 0.85rem;
      color: var(--color-text-light);
      margin-bottom: 12px;
      line-height: 1.4;
      display: -webkit-box;
      -webkit-line-clamp: 2;
      -webkit-box-orient: vertical;
      overflow: hidden;
    }

    .product-card__price {
      font-family: var(--font-heading);
      font-size: 1.35rem;
      font-weight: 700;
      color: var(--color-primary);
    }

    /* ==================== SEASONAL PICKS ==================== */
    .seasonal-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
      gap: 24px;
    }

    .seasonal-card {
      background: linear-gradient(135deg, #FFF9E6 0%, #FFF3CC 100%);
      border-radius: var(--radius-xl);
      padding: 28px;
      display: flex;
      gap: 20px;
      align-items: flex-start;
      box-shadow: var(--shadow-sm);
      transition: transform var(--transition-base), box-shadow var(--transition-base);
    }

    .seasonal-card:hover {
      transform: translateY(-4px);
      box-shadow: var(--shadow-md);
    }

    .seasonal-card__icon {
      flex-shrink: 0;
      width: 56px;
      height: 56px;
      background: white;
      border-radius: var(--radius-lg);
      display: flex;
      align-items: center;
      justify-content: center;
      box-shadow: var(--shadow-sm);
    }

    .seasonal-card__icon svg {
      width: 32px;
      height: 32px;
    }

    .seasonal-card__info {
      flex: 1;
    }

    .seasonal-card__name {
      font-family: var(--font-heading);
      font-size: 1.1rem;
      font-weight: 600;
      color: var(--color-text);
      margin-bottom: 6px;
    }

    .seasonal-card__desc {
      font-size: 0.9rem;
      color: var(--color-text-light);
      margin-bottom: 10px;
      line-height: 1.5;
    }

    .seasonal-card__price {
      font-family: var(--font-heading);
      font-size: 1.2rem;
      font-weight: 700;
      color: var(--color-accent-warm);
    }

    /* ==================== CATEGORIES ==================== */
    .categories-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
      gap: 20px;
    }

    .category-card {
      position: relative;
      height: 200px;
      border-radius: var(--radius-xl);
      overflow: hidden;
      cursor: pointer;
      box-shadow: var(--shadow-sm);
    }

    .category-card__bg {
      position: absolute;
      inset: 0;
      display: flex;
      align-items: center;
      justify-content: center;
      transition: transform var(--transition-slow);
    }

    .category-card:nth-child(1) .category-card__bg { background: linear-gradient(135deg, #FFECB3 0%, #FFD54F 100%); }
    .category-card:nth-child(2) .category-card__bg { background: linear-gradient(135deg, #C8E6C9 0%, #81C784 100%); }
    .category-card:nth-child(3) .category-card__bg { background: linear-gradient(135deg, #B3E5FC 0%, #4FC3F7 100%); }
    .category-card:nth-child(4) .category-card__bg { background: linear-gradient(135deg, #E1BEE7 0%, #BA68C8 100%); }
    .category-card:nth-child(5) .category-card__bg { background: linear-gradient(135deg, #FFCCBC 0%, #FF8A65 100%); }

    .category-card:hover .category-card__bg {
      transform: scale(1.08);
    }

    .category-card__icon {
      width: 80px;
      height: 80px;
      opacity: 0.4;
      transition: opacity var(--transition-base);
    }

    .category-card:hover .category-card__icon {
      opacity: 0.6;
    }

    .category-card__overlay {
      position: absolute;
      inset: 0;
      background: rgba(45, 106, 79, 0.85);
      display: flex;
      align-items: center;
      justify-content: center;
      opacity: 0;
      transition: opacity var(--transition-base);
    }

    .category-card:hover .category-card__overlay {
      opacity: 1;
    }

    .category-card__name {
      font-family: var(--font-heading);
      font-size: 1.35rem;
      font-weight: 700;
      color: white;
      text-align: center;
      padding: 20px;
      transform: translateY(10px);
      transition: transform var(--transition-base);
    }

    .category-card:hover .category-card__name {
      transform: translateY(0);
    }

    /* ==================== STORE LOCATOR ==================== */
    .locator {
      max-width: 680px;
      margin: 0 auto;
    }

    .locator__form {
      display: flex;
      gap: 12px;
      margin-bottom: 32px;
      flex-wrap: wrap;
    }

    .locator__input {
      flex: 1;
      min-width: 200px;
      padding: 16px 20px;
      font-family: var(--font-body);
      font-size: 1rem;
      border: 2px solid var(--color-border);
      border-radius: var(--radius-lg);
      background: var(--color-surface);
      color: var(--color-text);
      transition: border-color var(--transition-fast), box-shadow var(--transition-fast);
    }

    .locator__input:focus {
      outline: none;
      border-color: var(--color-primary);
      box-shadow: 0 0 0 4px rgba(45, 106, 79, 0.1);
    }

    .locator__input::placeholder {
      color: var(--color-text-light);
    }

    .locator__results {
      display: none;
      flex-direction: column;
      gap: 16px;
    }

    .locator__results.is-visible {
      display: flex;
      animation: fadeInUp 0.3s ease-out;
    }

    .store-card {
      background: var(--color-surface);
      border-radius: var(--radius-xl);
      padding: 24px;
      box-shadow: var(--shadow-sm);
      display: grid;
      grid-template-columns: 1fr auto;
      gap: 16px;
      align-items: center;
      transition: transform var(--transition-fast), box-shadow var(--transition-fast);
    }

    .store-card:hover {
      transform: translateY(-2px);
      box-shadow: var(--shadow-md);
    }

    .store-card__name {
      font-family: var(--font-heading);
      font-size: 1.2rem;
      font-weight: 600;
      color: var(--color-primary);
      margin-bottom: 6px;
    }

    .store-card__address {
      font-size: 0.95rem;
      color: var(--color-text-light);
      margin-bottom: 4px;
    }

    .store-card__hours {
      font-size: 0.9rem;
      color: var(--color-text);
      font-weight: 500;
    }

    .store-card__distance {
      text-align: right;
    }

    .store-card__distance-value {
      font-family: var(--font-heading);
      font-size: 1.5rem;
      font-weight: 700;
      color: var(--color-accent-warm);
    }

    .store-card__distance-label {
      font-size: 0.8rem;
      color: var(--color-text-light);
    }

    /* ==================== NEWSLETTER ==================== */
    .newsletter {
      background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-primary-dark) 100%);
      border-radius: var(--radius-xl);
      padding: 60px 40px;
      text-align: center;
      position: relative;
      overflow: hidden;
    }

    .newsletter::before {
      content: '';
      position: absolute;
      top: -50%;
      right: -20%;
      width: 400px;
      height: 400px;
      background: radial-gradient(circle, rgba(255,255,255,0.1) 0%, transparent 70%);
      pointer-events: none;
    }

    .newsletter__title {
      font-family: var(--font-heading);
      font-size: clamp(1.8rem, 4vw, 2.2rem);
      font-weight: 700;
      color: white;
      margin-bottom: 12px;
      position: relative;
    }

    .newsletter__subtitle {
      font-size: 1.1rem;
      color: rgba(255,255,255,0.85);
      margin-bottom: 32px;
      max-width: 480px;
      margin-left: auto;
      margin-right: auto;
      position: relative;
    }

    .newsletter__form {
      display: flex;
      gap: 12px;
      justify-content: center;
      flex-wrap: wrap;
      position: relative;
    }

    .newsletter__input {
      flex: 1;
      min-width: 260px;
      max-width: 380px;
      padding: 16px 20px;
      font-family: var(--font-body);
      font-size: 1rem;
      border: 2px solid rgba(255,255,255,0.3);
      border-radius: var(--radius-lg);
      background: rgba(255,255,255,0.95);
      color: var(--color-text);
      transition: border-color var(--transition-fast), box-shadow var(--transition-fast);
    }

    .newsletter__input:focus {
      outline: none;
      border-color: var(--color-accent);
      box-shadow: 0 0 0 4px rgba(244, 162, 97, 0.3);
    }

    .newsletter__input::placeholder {
      color: var(--color-text-light);
    }

    .newsletter__btn {
      padding: 16px 32px;
      background: var(--color-accent);
      color: white;
      font-family: var(--font-body);
      font-weight: 700;
      font-size: 1rem;
      border: none;
      border-radius: var(--radius-lg);
      cursor: pointer;
      transition: all var(--transition-fast);
      white-space: nowrap;
    }

    .newsletter__btn:hover {
      background: var(--color-accent-warm);
      transform: translateY(-2px);
    }

    .newsletter__btn:active {
      transform: scale(0.97);
    }

    .newsletter__confirmation {
      display: none;
      margin-top: 20px;
      padding: 16px 24px;
      background: rgba(255,255,255,0.15);
      border-radius: var(--radius-md);
      color: white;
      font-weight: 600;
      position: relative;
    }

    .newsletter__confirmation.is-visible {
      display: block;
      animation: fadeInUp 0.3s ease-out;
    }

    /* ==================== FOOTER ==================== */
    .footer {
      background: var(--color-primary-dark);
      color: white;
      padding: 64px 24px 32px;
    }

    .footer__inner {
      max-width: var(--max-width);
      margin: 0 auto;
    }

    .footer__grid {
      display: grid;
      grid-template-columns: 2fr repeat(3, 1fr);
      gap: 48px;
      margin-bottom: 48px;
    }

    .footer__brand {
      max-width: 280px;
    }

    .footer__logo {
      display: flex;
      align-items: center;
      gap: 10px;
      margin-bottom: 16px;
    }

    .footer__logo svg {
      width: 36px;
      height: 36px;
    }

    .footer__logo-text {
      font-family: var(--font-heading);
      font-size: 1.3rem;
      font-weight: 700;
    }

    .footer__desc {
      font-size: 0.9rem;
      color: rgba(255,255,255,0.7);
      line-height: 1.6;
    }

    .footer__heading {
      font-family: var(--font-heading);
      font-size: 1rem;
      font-weight: 600;
      margin-bottom: 20px;
      color: var(--color-accent);
    }

    .footer__links {
      list-style: none;
      display: flex;
      flex-direction: column;
      gap: 10px;
    }

    .footer__link {
      color: rgba(255,255,255,0.75);
      text-decoration: none;
      font-size: 0.9rem;
      transition: color var(--transition-fast);
    }

    .footer__link:hover {
      color: white;
    }

    .footer__bottom {
      padding-top: 32px;
      border-top: 1px solid rgba(255,255,255,0.1);
      text-align: center;
    }

    .footer__tagline {
      font-size: 0.9rem;
      color: rgba(255,255,255,0.5);
    }

    /* ==================== ANIMATIONS ==================== */
    @keyframes fadeInUp {
      from {
        opacity: 0;
        transform: translateY(20px);
      }
      to {
        opacity: 1;
        transform: translateY(0);
      }
    }

    @keyframes fadeInDown {
      from {
        opacity: 0;
        transform: translateY(-20px);
      }
      to {
        opacity: 1;
        transform: translateY(0);
      }
    }

    /* Reduced motion */
    @media (prefers-reduced-motion: reduce) {
      *, *::before, *::after {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
      }
      html {
        scroll-behavior: auto;
      }
    }

    /* ==================== RESPONSIVE ==================== */
    @media (max-width: 768px) {
      .nav {
        display: none;
      }

      .mobile-menu-btn {
        display: flex;
      }

      .header__inner {
        height: 64px;
      }

      .hero {
        padding: 60px 20px 80px;
      }

      .section {
        padding: 60px 20px;
      }

      .stats__inner {
        grid-template-columns: repeat(2, 1fr);
        gap: 24px;
      }

      .carousel__btn {
        display: none;
      }

      .product-card {
        flex: 0 0 220px;
      }

      .footer__grid {
        grid-template-columns: repeat(2, 1fr);
        gap: 32px;
      }

      .footer__brand {
        grid-column: span 2;
        max-width: 100%;
      }
    }

    @media (max-width: 480px) {
      .stats__inner {
        grid-template-columns: 1fr 1fr;
        gap: 20px;
      }

      .stat__number {
        font-size: 2rem;
