  <script>
    // Carousel navigation
    const track = document.getElementById('carousel-track');
    const prevBtn = document.getElementById('carousel-prev');
    const nextBtn = document.getElementById('carousel-next');

    if (track && prevBtn && nextBtn) {
      const scrollAmount = 280;

      prevBtn.addEventListener('click', () => {
        track.scrollBy({ left: -scrollAmount, behavior: 'smooth' });
      });

      nextBtn.addEventListener('click', () => {
        track.scrollBy({ left: scrollAmount, behavior: 'smooth' });
      });

      // Hide arrows at ends
      track.addEventListener('scroll', () => {
        prevBtn.style.opacity = track.scrollLeft <= 10 ? '0.4' : '1';
        prevBtn.style.pointerEvents = track.scrollLeft <= 10 ? 'none' : 'auto';
        const maxScroll = track.scrollWidth - track.clientWidth;
        nextBtn.style.opacity = track.scrollLeft >= maxScroll - 10 ? '0.4' : '1';
        nextBtn.style.pointerEvents = track.scrollLeft >= maxScroll - 10 ? 'none' : 'auto';
      });
    }

    // Store locator
    const locatorForm = document.getElementById('locator-form');
    const locatorResults = document.getElementById('locator-results');

    if (locatorForm && locatorResults) {
      locatorForm.addEventListener('submit', (e) => {
        e.preventDefault();
        const zipInput = document.getElementById('zip-input');
        if (zipInput.value.length >= 5) {
          locatorResults.classList.add('is-visible');
          locatorResults.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
        }
      });
    }

    // Newsletter
    const newsletterForm = document.getElementById('newsletter-form');
    const newsletterConfirmation = document.getElementById('newsletter-confirmation');

    if (newsletterForm && newsletterConfirmation) {
      newsletterForm.addEventListener('submit', (e) => {
        e.preventDefault();
        newsletterConfirmation.classList.add('is-visible');
        newsletterForm.reset();
      });
    }
  </script>
